/**
 * MARKET BRIEF — a short, plain-language explanation of WHY an asset or pair is bullish / bearish right now,
 * plus a forward-looking section (what is scheduled, what would change the call, what the counter-forces are).
 *
 * Accuracy by construction: nothing is generated by a language model. Every sentence is rendered from the
 * engine's own numbers (scores, indicator prints, forecasts, scheduled releases) through two fixed phrase books —
 * English and Urdu — so the two languages always say exactly the same thing. Indicator names, tickers and numbers
 * are kept as published. If a fact is not available, the sentence is omitted rather than guessed.
 */
import type { AssetResult, IndicatorResult, MacroSnapshot, PairResult, Bias } from './types.js';

export interface L { en: string; ur: string }
export interface BriefLine extends L { tone?: 'bull' | 'bear' | 'neutral' | 'info'; at?: number }
export interface Brief {
  symbol: string; display: string; kind: 'asset' | 'pair'; assetClass: string;
  bias: Bias; biasLabel: L; score: number | null; confidence: number; updatedAt: string; asOf: string;
  headline: L; why: BriefLine[]; outlook: BriefLine[]; counter: BriefLine[]; disclaimer: L;
}

const BIAS_EN: Record<Bias, string> = { STRONG_BULLISH: 'Strong Bullish', BULLISH: 'Bullish', MILD_BULLISH: 'Mild Bullish', NEUTRAL: 'Neutral', MILD_BEARISH: 'Mild Bearish', BEARISH: 'Bearish', STRONG_BEARISH: 'Strong Bearish' };
const BIAS_UR: Record<Bias, string> = { STRONG_BULLISH: 'مضبوط تیزی', BULLISH: 'تیزی', MILD_BULLISH: 'ہلکی تیزی', NEUTRAL: 'غیر جانبدار', MILD_BEARISH: 'ہلکی مندی', BEARISH: 'مندی', STRONG_BEARISH: 'مضبوط مندی' };
export const biasLabelL = (b: Bias): L => ({ en: BIAS_EN[b], ur: `${BIAS_UR[b]} (${BIAS_EN[b]})` });

const sgn = (n: number) => (n > 0 ? `+${Math.round(n)}` : `${Math.round(n)}`);
const num = (v: number) => (Math.abs(v) >= 100 ? String(Math.round(v * 10) / 10) : String(Math.round(v * 100) / 100));
const withUnit = (v: number, unit?: string) => { const u = (unit || '').trim(); return /^[%]|^(K|M|B|T)$/i.test(u) ? `${num(v)}${u}` : u ? `${num(v)} ${u}` : num(v); };
const stripStage = (s: string) => s.toLowerCase().replace(/\s*\((prel|final|flash|adv|advance|revised)[^)]*\)\s*$/i, '').replace(/\s+/g, ' ').trim();

const THRESHOLDS = [60, 30, 10, -10, -30, -60];
function stability(score: number, label: string): BriefLine[] {
  const up = THRESHOLDS.filter((t) => t > score).pop(); // nearest above
  const down = THRESHOLDS.filter((t) => t <= score).shift(); // nearest at/below
  const bUp = up === undefined ? null : up, bDown = down === undefined ? null : down;
  const names = (t: number): Bias => (t >= 60 ? 'STRONG_BULLISH' : t >= 30 ? 'BULLISH' : t >= 10 ? 'MILD_BULLISH' : t > -10 ? 'NEUTRAL' : t > -30 ? 'MILD_BEARISH' : t > -60 ? 'BEARISH' : 'STRONG_BEARISH');
  const out: BriefLine[] = [];
  if (bUp !== null && bDown !== null) {
    const toUp = Math.round(bUp - score), toDown = Math.round(score - bDown);
    out.push({
      tone: 'info',
      en: `${label} sits at ${sgn(score)}: it needs ${toUp} more points to reach ${BIAS_EN[names(bUp)]}, and would drop to ${BIAS_EN[names(bDown - 0.1)]} if it falls below ${sgn(bDown)} (${toDown} points lower).`,
      ur: `${label} کا اسکور ${sgn(score)} ہے: ${BIAS_UR[names(bUp)]} (${BIAS_EN[names(bUp)]}) تک پہنچنے کے لیے مزید ${toUp} پوائنٹس درکار ہیں، اور اگر یہ ${sgn(bDown)} سے نیچے گیا (${toDown} پوائنٹس کم) تو رجحان ${BIAS_UR[names(bDown - 0.1)]} (${BIAS_EN[names(bDown - 0.1)]}) میں بدل جائے گا۔`,
    });
  }
  return out;
}

const whenL = (at: number, now: number): L => {
  const m = Math.round((at - now) / 60000); const d = new Date(at); const utc = `${d.toISOString().slice(0, 10)} ${d.toISOString().slice(11, 16)} UTC`;
  if (m < 60) return { en: `in ${Math.max(1, m)} min (${utc})`, ur: `${Math.max(1, m)} منٹ میں (${utc})` };
  if (m < 48 * 60) { const h = Math.round(m / 60); return { en: `in ${h} h (${utc})`, ur: `${h} گھنٹوں میں (${utc})` }; }
  const dd = Math.round(m / 1440); return { en: `in ${dd} days (${utc})`, ur: `${dd} دن میں (${utc})` };
};

interface Ind extends IndicatorResult { pillar: string }
const allInds = (a: AssetResult): Ind[] => a.pillars.flatMap((p) => p.indicators.map((i) => ({ ...i, pillar: p.name })));
const polarityOf = (i: Ind | undefined): 1 | -1 | 0 => { const m = i?.polarityNote?.match(/higher\s*=\s*(bullish|bearish)/i); return m ? (m[1].toLowerCase() === 'bullish' ? 1 : -1) : 0; };

function driverLine(i: Ind, label: string): BriefLine | null {
  const o = i.observation; if (!o || i.score === null) return null;
  const parts = [{ en: `printed ${withUnit(o.actual, o.unit)}`, ur: `${withUnit(o.actual, o.unit)} رہی` }];
  const fc = o.forecast !== null ? { en: `forecast ${withUnit(o.forecast, o.unit)}`, ur: `متوقع ${withUnit(o.forecast, o.unit)}` } : null;
  const pv = o.previous !== null ? { en: `previous ${withUnit(o.previous, o.unit)}`, ur: `پچھلی ${withUnit(o.previous, o.unit)}` } : null;
  const ctx = [fc, pv].filter(Boolean) as L[];
  const per = o.period ? ` [${o.period}]` : '';
  const bull = i.score > 0;
  const stale = i.status === 'stale';
  return {
    tone: bull ? 'bull' : 'bear',
    en: `${i.name}${per} ${parts[0].en}${ctx.length ? ` (${ctx.map((c) => c.en).join(', ')})` : ''} — ${bull ? `supports ${label}` : `weighs on ${label}`} (${bull ? 'bullish' : 'bearish'}, ${sgn(i.score)})${stale ? '; reading is not recent' : ''}.`,
    ur: `${i.name}${per}: ${parts[0].ur}${ctx.length ? ` (${ctx.map((c) => c.ur).join('، ')})` : ''} — یہ ${label} کے لیے ${bull ? 'سازگار (تیزی کا عنصر)' : 'دباؤ کا باعث (مندی کا عنصر)'} ہے (${sgn(i.score)})${stale ? '؛ ڈیٹا تازہ نہیں' : ''}۔`,
  };
}

function topDrivers(a: AssetResult, n: number): Ind[] {
  return allInds(a).filter((i) => i.score !== null && i.status !== 'missing' && i.observation).sort((x, y) => Math.abs((y.score as number) * y.effectiveWeight) - Math.abs((x.score as number) * x.effectiveWeight)).slice(0, n);
}

function pillarLines(a: AssetResult, label: string): BriefLine[] {
  const ps = a.pillars.filter((p) => p.score !== null && p.coverage >= 0.3);
  if (ps.length < 2) return [];
  const best = [...ps].sort((x, y) => (y.score as number) - (x.score as number))[0], worst = [...ps].sort((x, y) => (x.score as number) - (y.score as number))[0];
  if (best.id === worst.id) return [];
  return [{ tone: 'info', en: `Strongest pillar for ${label}: ${best.name} (${sgn(best.score as number)}); weakest: ${worst.name} (${sgn(worst.score as number)}).`, ur: `${label} کا سب سے مضبوط پہلو: ${best.name} (${sgn(best.score as number)})؛ سب سے کمزور: ${worst.name} (${sgn(worst.score as number)})۔` }];
}

function counterLines(a: AssetResult, label: string): BriefLine[] {
  if (a.score === null || Math.abs(a.score) < 10) return [];
  const against = a.pillars.filter((p) => p.score !== null && p.coverage >= 0.3 && Math.sign(p.score as number) === -Math.sign(a.score as number) && Math.abs(p.score as number) >= 8).sort((x, y) => Math.abs(y.score as number) - Math.abs(x.score as number)).slice(0, 2);
  return against.map((p) => ({ tone: 'neutral' as const, en: `Counter-force: ${p.name} is ${sgn(p.score as number)} for ${label}, pulling against the current ${a.score! > 0 ? 'bullish' : 'bearish'} lean. If it strengthens, the bias weakens.`, ur: `مخالف قوت: ${label} کے لیے ${p.name} کا اسکور ${sgn(p.score as number)} ہے جو موجودہ ${a.score! > 0 ? 'تیزی' : 'مندی'} کے رجحان کے خلاف کھینچ رہا ہے۔ اگر یہ مضبوط ہوا تو رجحان کمزور پڑ جائے گا۔` }));
}

type Up = MacroSnapshot['upcoming'][number];
function eventLine(u: Up, a: AssetResult | undefined, pairSign: 1 | -1, label: string, now: number, pairLabel?: string): BriefLine {
  const at = Date.parse(u.scheduledAt); const w = whenL(at, now);
  const ind = a ? allInds(a).find((i) => i.observation?.sourceTitle && stripStage(i.observation.sourceTitle) === stripStage(u.title)) : undefined;
  const pol = polarityOf(ind) * pairSign;
  const unit = ind?.observation?.unit;
  const fcs = u.forecast !== null ? `forecast ${withUnit(u.forecast, unit)}` : null, pvs = u.previous !== null ? `previous ${withUnit(u.previous, unit)}` : null;
  const fcu = u.forecast !== null ? `متوقع ${withUnit(u.forecast, unit)}` : null, pvu = u.previous !== null ? `پچھلی ${withUnit(u.previous, unit)}` : null;
  const tgt = pairLabel || label;
  let enDir = '', urDir = '';
  if (pol !== 0) {
    enDir = ` A result above forecast would be ${pol > 0 ? 'bullish' : 'bearish'} for ${tgt}; below forecast, ${pol > 0 ? 'bearish' : 'bullish'}.`;
    urDir = ` اگر نتیجہ توقع سے اوپر آئے تو ${tgt} کے لیے ${pol > 0 ? 'تیزی' : 'مندی'}، اور نیچے آئے تو ${pol > 0 ? 'مندی' : 'تیزی'} کا اشارہ ہوگا۔`;
  } else { enDir = ' A surprise versus forecast can move the score either way.'; urDir = ' توقع سے ہٹ کر نتیجہ اسکور کو کسی بھی طرف لے جا سکتا ہے۔'; }
  return {
    tone: 'info', at,
    en: `${u.asset} · ${u.title} is due ${w.en}${fcs || pvs ? ` (${[fcs, pvs].filter(Boolean).join(', ')})` : ''}.${enDir}`,
    ur: `${u.asset} · ${u.title} ${w.ur} آنے والا ہے${fcu || pvu ? ` (${[fcu, pvu].filter(Boolean).join('، ')})` : ''}۔${urDir}`,
  };
}

const DISCLAIMER: L = {
  en: 'This brief is generated automatically from live economic data, positioning and scheduled releases. It describes the fundamental lean, not a price target or a trade signal.',
  ur: 'یہ خلاصہ براہِ راست معاشی ڈیٹا، پوزیشننگ اور طے شدہ ریلیزز سے خودکار طور پر بنایا گیا ہے۔ یہ بنیادی رجحان بتاتا ہے، قیمت کا ہدف یا ٹریڈ سگنل نہیں۔',
};

export function assetBrief(a: AssetResult, s: MacroSnapshot, now = Date.now()): Brief {
  const label = a.symbol; const sc = a.score;
  const why: BriefLine[] = [];
  if (sc === null) {
    why.push({ tone: 'neutral', en: `Not enough live data to score ${a.name} yet.`, ur: `${a.name} کو اسکور کرنے کے لیے ابھی کافی لائیو ڈیٹا موجود نہیں۔` });
  } else {
    for (const d of topDrivers(a, 4)) { const l = driverLine(d, label); if (l) why.push(l); }
    why.push(...pillarLines(a, label));
  }
  const outlook: BriefLine[] = [];
  const ups = s.upcoming.filter((u) => u.asset === a.symbol && Date.parse(u.scheduledAt) > now).sort((x, y) => Date.parse(x.scheduledAt) - Date.parse(y.scheduledAt));
  const hi = ups.filter((u) => /high|3/i.test(u.importance)); const pick = (hi.length ? hi : ups).slice(0, 3);
  for (const u of pick) outlook.push(eventLine(u, a, 1, label, now));
  if (!pick.length) outlook.push({ tone: 'info', en: `No scheduled release for ${label} in the data window; the bias will move mainly with new prints and market-based inputs.`, ur: `${label} کے لیے ڈیٹا کی مدت میں کوئی طے شدہ ریلیز نہیں؛ رجحان زیادہ تر نئے اعداد و شمار اور مارکیٹ پر مبنی عوامل سے بدلے گا۔` });
  if (sc !== null) outlook.push(...stability(sc, label));
  if (sc !== null && a.confidence < 60) outlook.push({ tone: 'neutral', en: `Data coverage is ${Math.round(a.confidence)}%, so treat this lean with lower conviction until more inputs report.`, ur: `ڈیٹا کی کوریج ${Math.round(a.confidence)}% ہے، اس لیے مزید ڈیٹا آنے تک اس رجحان پر کم اعتماد رکھیں۔` });
  const head: L = sc === null
    ? { en: `${label} (${a.name}): not enough data to call a bias yet.`, ur: `${label} (${a.name}): رجحان طے کرنے کے لیے ابھی کافی ڈیٹا نہیں۔` }
    : { en: `${label} (${a.name}) is ${BIAS_EN[a.bias]} — score ${sgn(sc)}, data confidence ${Math.round(a.confidence)}%.`, ur: `${label} (${a.name}) فی الحال ${BIAS_UR[a.bias]} (${BIAS_EN[a.bias]}) ہے — اسکور ${sgn(sc)}، ڈیٹا اعتماد ${Math.round(a.confidence)}%۔` };
  return { symbol: a.symbol, display: a.symbol, kind: 'asset', assetClass: a.assetClass, bias: a.bias, biasLabel: biasLabelL(a.bias), score: sc, confidence: a.confidence, updatedAt: a.updatedAt, asOf: s.generatedAt, headline: head, why, outlook, counter: sc === null ? [] : counterLines(a, label), disclaimer: DISCLAIMER };
}

export function pairBrief(p: PairResult, base: AssetResult | undefined, quote: AssetResult | undefined, s: MacroSnapshot, now = Date.now()): Brief {
  const sc = p.score; const why: BriefLine[] = [];
  if (sc !== null && p.baseScore !== null && p.quoteScore !== null) {
    const stronger = p.baseScore >= p.quoteScore ? p.base : p.quote;
    why.push({ tone: sc >= 0 ? 'bull' : 'bear', en: `${p.base} scores ${sgn(p.baseScore)} and ${p.quote} scores ${sgn(p.quoteScore)}; ${stronger} is the stronger side, so the pair leans ${sc > 0 ? 'bullish' : sc < 0 ? 'bearish' : 'neutral'}.`, ur: `${p.base} کا اسکور ${sgn(p.baseScore)} اور ${p.quote} کا ${sgn(p.quoteScore)} ہے؛ ${stronger} مضبوط فریق ہے، اس لیے جوڑی کا رجحان ${sc > 0 ? 'تیزی' : sc < 0 ? 'مندی' : 'غیر جانبدار'} کی طرف ہے۔` });
  }
  const side = (a: AssetResult | undefined, sign: 1 | -1, lab: string, n: number) => {
    if (!a) return [] as BriefLine[];
    return topDrivers(a, n).map((d) => {
      const l = driverLine(d, lab); if (!l) return null;
      const bullPair = sign * (d.score as number) > 0;
      return { ...l, tone: bullPair ? 'bull' as const : 'bear' as const, en: l.en.replace(/\.$/, `, which is ${bullPair ? 'bullish' : 'bearish'} for ${p.display}.`), ur: l.ur.replace(/۔$/, `، جو ${p.display} کے لیے ${bullPair ? 'تیزی' : 'مندی'} کا اشارہ ہے۔`) };
    }).filter(Boolean) as BriefLine[];
  };
  why.push(...side(base, 1, p.base, 2), ...side(quote, -1, p.quote, 2));
  if (p.retailSentiment) {
    const r = p.retailSentiment; const crowdLong = r.longPct >= 50;
    why.push({ tone: 'info', en: `Retail traders are ${Math.round(r.longPct)}% long / ${Math.round(r.shortPct)}% short (${r.source}); the crowd is mostly ${crowdLong ? 'long' : 'short'}, which is a ${r.contrarianScore > 0 ? 'bullish' : r.contrarianScore < 0 ? 'bearish' : 'neutral'} contrarian signal.`, ur: `ریٹیل ٹریڈرز ${Math.round(r.longPct)}% لانگ / ${Math.round(r.shortPct)}% شارٹ ہیں (${r.source})؛ بھیڑ زیادہ تر ${crowdLong ? 'لانگ' : 'شارٹ'} ہے، جو ${r.contrarianScore > 0 ? 'تیزی' : r.contrarianScore < 0 ? 'مندی' : 'غیر جانبدار'} کے حق میں الٹا (contrarian) اشارہ ہے۔` });
  }
  const outlook: BriefLine[] = [];
  const mk = (asset: AssetResult | undefined, sym: string, sign: 1 | -1) => s.upcoming.filter((u) => u.asset === sym && Date.parse(u.scheduledAt) > now).map((u) => eventLine(u, asset, sign, sym, now, p.display));
  const evs = [...mk(base, p.base, 1), ...mk(quote, p.quote, -1)].sort((x, y) => (x.at as number) - (y.at as number)).slice(0, 4);
  outlook.push(...evs);
  if (!evs.length) outlook.push({ tone: 'info', en: `No scheduled release for ${p.base} or ${p.quote} in the data window.`, ur: `${p.base} یا ${p.quote} کے لیے ڈیٹا کی مدت میں کوئی طے شدہ ریلیز نہیں۔` });
  if (sc !== null) outlook.push(...stability(sc, p.display));
  const counter: BriefLine[] = [];
  if (sc !== null && Math.abs(sc) >= 10) {
    const weakSide = sc > 0 ? base : quote; const strongSide = sc > 0 ? quote : base;
    if (weakSide && strongSide) {
      counter.push({ tone: 'neutral', en: `The call changes if ${sc > 0 ? p.quote : p.base} strengthens or ${sc > 0 ? p.base : p.quote} weakens; watch the releases above for both currencies.`, ur: `اگر ${sc > 0 ? p.quote : p.base} مضبوط ہو یا ${sc > 0 ? p.base : p.quote} کمزور پڑے تو رجحان بدل سکتا ہے؛ دونوں کی اوپر دی گئی ریلیزز پر نظر رکھیں۔` });
    }
  }
  const head: L = sc === null
    ? { en: `${p.display}: not enough data to call a bias yet.`, ur: `${p.display}: رجحان طے کرنے کے لیے ابھی کافی ڈیٹا نہیں۔` }
    : { en: `${p.display} is ${BIAS_EN[p.bias]} — score ${sgn(sc)}, data confidence ${Math.round(p.confidence)}%.`, ur: `${p.display} فی الحال ${BIAS_UR[p.bias]} (${BIAS_EN[p.bias]}) ہے — اسکور ${sgn(sc)}، ڈیٹا اعتماد ${Math.round(p.confidence)}%۔` };
  return { symbol: p.symbol, display: p.display, kind: 'pair', assetClass: p.assetClass, bias: p.bias, biasLabel: biasLabelL(p.bias), score: sc, confidence: p.confidence, updatedAt: s.generatedAt, asOf: s.generatedAt, headline: head, why, outlook, counter, disclaimer: DISCLAIMER };
}
